('health',2,'发抖','冷；害怕（打雷、放炮、洗澡）；紧张；疼痛','保暖安抚；伴随没精神要检查身体','medical',NULL,'EXCEL','SEED-DOG-MANUAL',2,NOW(),NOW(),0),('health',2,'躲起来不见人','害怕（被打骂后）；身体不舒服；来了陌生人','别强行拉出来，安静陪伴观察','medical',NULL,'EXCEL','SEED-DOG-MANUAL',2,NOW(),NOW(),0),('health',2,'精神萎靡、一直趴着','没睡好；天气太热；身体不舒服','连续一两天没精神+不吃不喝就要就医','medical',NULL,'EXCEL','SEED-DOG-MANUAL',2,NOW(),NOW(),0),('behavior',1,'尾巴竖直、尾尖微微向前弯','心情愉悦、友好问候、表示信任','最经典的"欢迎回家"姿势，常伴随咕噜声与轻蹭','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'尾巴大幅左右甩动（拍打地面）','烦躁、不耐烦、被打扰','与狗不同，猫大幅甩尾不是开心，而是警告','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'尾巴尖轻微抖动','专注、好奇、轻度兴奋','常见于观察窗外小鸟或刚听到动静','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'尾巴下垂、夹在两腿间','害怕、紧张、示弱、顺从','伴随身体压低、耳朵后压','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'尾巴膨大（炸毛）、呈刷状','恐惧、防御、威吓','让自己"变大"吓退对方','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'尾巴贴地平伸、低摆','专注跟踪猎物、捕猎前姿态','准备扑击的前奏','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'尾巴绕人或绕另一只猫','亲昵、社交、表达占有','猫与人之间常表现为用尾巴勾手臂','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'缓慢眨眼（眯眼看你）','表达爱意与信任，又称"猫之吻"','可回以同样缓慢眨眼加深情感','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'瞪大眼、瞳孔圆形扩大','兴奋、紧张、恐惧，或光线暗','玩逗猫棒时或遇威胁时常见','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'瞳孔缩成细线','光线强或情绪紧绷','强光下正常；伴随炸毛=高度警戒','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'对主人侧头','好奇、试图判断声音来源','在判断陌生声音时常见','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'露出肚子（四脚朝天）','信任与放松，但通常不是邀请摸','多数情况下摸肚子会被抓或咬','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'"面包蹲坐"（loaf，爪子藏在身体下）','放松、舒适、保温','说明环境让猫有安全感','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'"夹紧"蹲坐（脚收身下）','紧张、寒冷或不适','持续此姿势且不吃东西需排查健康','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'"猪猪趴"（sploct，后腿伸到身后）','放松 + 凉爽（肚皮贴地散热）','天热或极度放松时常见','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'拱背、毛发直立','恐惧、威胁、准备战斗','常伴随哈气、嘶叫','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'身体低贴地面、耳朵后压','害怕、试图躲避','是猫最常见的恐惧表现','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'身体直立、尾巴笔直（"尾巴翘天"）','自信、放松、巡视领地','对熟悉环境表达"这是我地盘"','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'蹭你的腿/手/脸','用脸颊腺体标记气味、宣示占有','是在把它的气味和你混合在一起','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'用头抵你的手/脸（headbutt）','亲昵、信任、社交标记','是高浓度的爱意表达','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'用下巴或脸颊蹭家具、墙角','标记领地、留下气味','可视作"签到"','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'揉面/踩奶（踩踏柔软物体）','安心、放松、回忆起幼猫吮乳本能','常见于毯子、被子、主人肚子','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'轻咬（无力度）','亲昵、玩闹、不想被打扰','称"爱咬"，属于社交行为','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'用力咬（带嘶声）','警告、疼痛、防御','绝对要停手，给它空间','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'舔你的手/头发','信任、表达爱意、帮你"清洁"','也是社交互惠','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'互相梳毛（allogrooming）','亲昵、信任、群体归属','关系好的猫之间常见','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'耳朵朝前竖立','警觉、好奇、放松','最放松的姿态之一','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'耳朵朝后压平（飞机耳）','紧张、不悦、警告或恐惧','伴随哈气、低吼要远离','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'耳朵朝两侧（"蝙蝠耳"）','集中听微弱声音、警戒','也用于读取声源方向','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'耳朵单侧前倾','专注某一声源','像在"调焦"','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'耳朵不停转动','持续监听、焦虑或兴趣','新环境中很常见','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'胡须向前突出、聚拢','专注、好奇、捕猎评估','如在研究新玩具或猎物','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'胡须向后贴脸颊','紧张、害怕、防御','身体通常伴随压低','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'胡须自然下垂','放松、平静','默认状态','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'鼻吻碰触（两猫鼻对鼻）','友好问候、确认身份','猫打招呼的第一动作','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'鼻子微凉湿润','健康','猫鼻湿润是正常状态（短时间干燥也属正常）','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'嘴微张、上唇后翻（Flehmen 反应）','嗅闻信息素、分析同类化学信号','公猫闻到母猫尿液时常见','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'张大嘴露出牙齿（无声张嘴）','嗅闻更强的信息素','为"裂唇嗅反应"的加剧版','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'打响鼻（短促喷气）','轻度警觉、试探、表示不满','也可能是过敏或鼻腔异物','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'缩成一团睡觉','保温、防御、深度放松','寒冷或陌生环境的默认睡姿','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'侧躺、四肢伸展睡','放松+散热、对环境高度信任','夏天常在凉地板上这么睡','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'仰躺睡觉','极度放松、信任、舒适','通常发生在熟悉的猫与主人身边','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'半闭眼打盹（"禅坐"）','放松但保持警觉','可随时起身的状态','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'突然抽搐尾巴尖（睡眠中）','做梦','猫也会做梦，常见轻微动作','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'爪子轻轻压/踩你身上','信任、做记号、寻求安慰','亦称"踩奶"','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'爪子紧紧抓住你的手','怕摔、寻求安全感（幼猫更常见）','可轻声安抚','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'伸出爪子轻碰你（不伸出爪）','请求互动、想要食物或抚摸','是非常温和的"打扰"','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'爪子不伸出地拍打你','玩闹、警告、试探','是游戏也是"再想想"信号','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'玩弓姿势（前半身压低、后半身翘起）','邀请游戏、捕猎演练','经典"狩猎模式"','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'突然"疯跑"（Frenetic Random Activity Periods）','释放能量、捕猎本能','傍晚/夜里常见，是正常现象','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'尾巴根部快速颤动（贴着猫或人）','激动、占有、极度喜欢','你回到家的那一刻最常见','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'理毛后突然停下来盯着你','打断理毛关注你','代表它优先注意到你，是亲昵表现','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'短促"喵"（单声）','普通招呼、"你好"','猫与猫之间少用，是专门对人的社交语言','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'轻柔短促的"喵"','礼貌问好或轻度索求','常见于刚睡醒时的问候','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'连续多声"喵喵喵"','兴奋、欢迎、引起注意','回家时最常见','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'拉长声"喵~~~~~"','抱怨、强烈索求（多数是要食物）','伴随走来走去是"饭呢？饭呢？"','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'高频尖锐"喵"','惊讶、被吓、不满','突然看到虫或被踩到尾巴','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'低频短"喵"','不悦、警告','如正玩得开心被打断','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'反复小声"喵"（一停一停）','困惑、想被理解','常出现在找不到你的时候','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'"嗯嗯"短促鼻音','温和招呼、不想太打扰','相当于"嗯，是我"','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'"唔"闷哼','被触摸舒服时的回应','常伴随揉面','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'咕噜咕噜（短促）','满足、放松','常在吃奶、被抚摸时出现','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'咕噜咕噜（持续、高响）','表达亲密','但也用于自我安抚，如病痛或紧张时','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'咕噜声+鼻音颤音','极放松+亲近','是猫最柔和的声音之一','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'颤音（短促上升的"咩"）','友善打招呼','多猫家庭中母猫对幼猫用','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'"啾啾"（bird-like chirp）','观察窗外猎物时的捕猎兴奋','是捕捉不到猎物的"挫败+兴奋"','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'"咔咔"声（chattering，牙齿打颤）','极度捕猎兴奋、焦虑','看鸟或飞虫时特有','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'"嘎嘎"牙齿打颤声','高强度捕猎亢奋','有人认为是模仿猎物叫声','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'"咩~咩~"短绵羊叫声','玩耍或极度兴奋','个别猫的特殊表达，不普遍','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'"咔嗒咔嗒"（嘴上下磕碰）','轻度捕猎/模仿猎物','和"咔咔"类似但声音更清脆','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'咆哮（低沉、喉音）','强警告、不许靠近','已是攻击前奏','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'低吼（带振动）','愤怒或威胁','伴随弓背、炸毛','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'哈气（短促"呸"）','恐惧或警告','随时准备攻击','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'嘶嘶声（长嘶）','极度恐惧或威吓','猫的"最后警告"','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'长嚎（夜晚"啊呜~"）','未绝育公猫争夺地盘/求偶；母猫发情','建议尽早绝育可大幅减少','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'母猫发情期"嗷"叫','求偶','伴随打滚、蹭地','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'幼猫尖细"咪咪"声','找妈妈、冷、饿、求助','提示环境过冷或与母猫分离','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'短促尖"喵"（幼猫）','受惊或找同伴','幼猫离开同伴时常发出','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'沙哑"喵"或几乎无声','老年猫、喉咙发炎、咽部疾病','需就医检查','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'"嗬嗬"呼吸道杂音','呼吸道感染、哮喘、心脏问题','持续出现需就医','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'吞咽声（"咕"）','反胃、咽部异物、口炎','频繁出现需就医','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'睡觉时打呼噜','放松的鼻/软腭振动','短吻品种（加菲、英短）更常见','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'"嗯~"（闭眼呼气）','放松/被打断的小抗议','是被抱太久时常见','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'叹气般的"呼~"','放松、解气、结束一件事','和人类叹气相似','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'"咕——"（短促咕+轻声）','略不情愿但接受','如被抱起后轻声说"咕——"','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'"喵呜~"（末尾带颤音）','疑惑或提出问题','如"这是什么？为什么？"','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'"啊啊"连续哭喊','极度不适、疼痛或分离焦虑','与受惊叫接近但持续时间更长','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'夜间"啊呜~啊呜~"长嚎','老年猫认知障碍/迷路/疼痛','应与年轻猫发情区分','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'"嚓嚓"声（磨牙）','牙齿/口腔疾病','尤其吃饭时需关注','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'玩弄"咯咯"声','玩玩具时的兴奋短音','对某些玩具特有','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'"咕噜"声（强烈、节律稳定）','极度满足','代表"我是世界上最舒服的猫"','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'安静无言的凝视+微张嘴','高度警觉+评估','通常是它"看不懂"或犹豫要不要靠近','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'"咪"（短促）','礼貌打招呼/轻度索求','常发生在早晨你刚起床时','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'"咔嚓"咬东西的声音','捕猎、啃咬','伴随咬玩具或抓到"猎物"','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'"嗷"（突然大叫）','被踩到/剧痛/惊吓','通常对应了具体事件','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'"啊——"（长哀鸣）','强烈抗议、疼痛','被关在门外或不被允许上床时','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0),('behavior',1,'"咕咚"吞咽口水声','饥饿、口渴、口腔问题','若伴随大量流口水需就医','guide',NULL,'EXCEL','SEED-CAT-MANUAL',2,NOW(),NOW(),0)
;

